// Probe hooks on the UE3 renderer, its RHI and the Xbox D3D library
// (PROBES.md). The overrides are generated by tools/gen_hooks.py into
// src/hooks_gen.cpp from tools/hook_table.py; this header is the interface
// between them and the hand-written probes in src/probes.cpp.
#pragma once

#include <cstdint>

#include <rex/ppc.h>

// What a hook table entry is (tools/hook_table.py KINDS).
enum class Gears1ProbeKind : uint8_t {
  kCount,   // D3D library function only counted by gears1_d3d_observe
  kPass,    // scene renderer pass / sub-pass: traced ENTER/LEAVE, skippable
  kScope,   // nested scope that is tracked but not traced (e.g. DrawMesh)
  kPolicy,  // drawing-policy DrawShared: tags the following draws
  kDraw,    // D3D draw: traced with a state snapshot
  kEvent,   // other D3D call traced with its raw arguments
  kFrame,   // frame boundary
};

// Argument registers at entry, for post hooks (tools/hook_table.py 'post').
struct Gears1HookEntry {
  uint32_t r3, r4, r5, r6;
  double f1;
};

struct Gears1ProbeInfo {
  uint32_t address;
  const char* name;
  Gears1ProbeKind kind;
};

// Defined in src/hooks_gen.cpp.
extern const Gears1ProbeInfo kGears1Probes[];
extern const uint32_t kGears1ProbeCount;

// Called by the generated overrides. Enter returns true when the call must be
// skipped (gears1_probe_skip); the override then returns 0 in r3.
bool Gears1ProbeEnter(uint32_t id, PPCContext& ctx, uint8_t* base);
void Gears1ProbeLeave(uint32_t id);
void Gears1ProbePolicy(uint32_t id);
void Gears1ProbeDraw(uint32_t id, PPCContext& ctx, uint8_t* base);
void Gears1ProbeEvent(uint32_t id, PPCContext& ctx, uint8_t* base);
void Gears1ProbeFrameEnd(uint8_t* base);
// Pre hook of the D3D DepthBias / SlopeScaleDepthBias render-state setters:
// applies gears1_probe_depth_bias_scale / _negate to the value in r4.
void Gears1ProbeDepthBiasPre(PPCContext& ctx, uint8_t* base);

// Window focus and mouse buttons as seen by the thread pumping SDL events
// (src/native_input.cpp). SDL's focus and mouse state getters are main-thread
// only; guest threads read these instead.
bool Gears1WindowFocused();
uint32_t Gears1MouseButtons();  // SDL_BUTTON_*MASK bits

// Shader hashes (src/shader_dump.cpp): computed on bind while the dump or a
// probe trace wants them; 0 when unknown.
bool Gears1ProbeWantsShaderHashes();
uint64_t Gears1ShaderHash(uint32_t object);
